+++ b/src/domain/sites.js
@@ -0,0 +1,24 @@
+// Sites: the kitchens Larder serves. Every location belongs to one site, and
+// a batch belongs to the site of its location.
+import { AppError } from "../errors.js";
+
+/** The site a request uses when it names none. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** True when `locationId` is a location of `site` (any location when `site` is undefined). */
+export function locationInSite(store, locationId, site) {
+  const loc = store.data.locations.find((l) => l.id === locationId);
+  return Boolean(loc) && (site === undefined || loc.site === site);
+}
+
+/** True when the batch lies in a location of `site` (any batch when `site` is undefined). */
+export function batchInSite(store, batch, site) {
+  return site === undefined || locationInSite(store, batch.location, site);
+}
