@@ -0,0 +1,64 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "nowhere" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /nowhere/);
+});
+
+test("without the header the site is main; annex sees no stock yet", async () => {
+  const { handle } = app();
+  const main = await handle({ path: "/items" });
+  assert.equal(main.body.find((i) => i.id === 1).onHand, 10);
+  const other = await handle({ path: "/items", headers: annex });
+  assert.equal(other.body.find((i) => i.id === 1).onHand, 0);
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body, []);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 0);
+  const alerts = (await handle({ path: "/alerts", headers: annex })).body;
+  assert.deepEqual(alerts.expiring, []);
+  assert.ok(alerts.lowStock.length > 0);
+});
+
+test("receiving, cooking and stock-takes stay inside the site", async () => {
+  const { handle, store } = app();
+  const draft = await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } });
+  await handle({ method: "POST", path: `/orders/${draft.body.id}/send` });
+  const bad = await handle({ method: "POST", path: `/orders/${draft.body.id}/receive`, headers: annex, body: { lots: [{ lot: "x", expires: null, location: "dry" }] } });
+  assert.equal(bad.body.error.code, "unknown_location");
+  const ok = await handle({ method: "POST", path: `/orders/${draft.body.id}/receive`, headers: annex, body: { lots: [{ lot: "x", expires: null, location: "annex-fridge" }] } });
+  assert.equal(ok.status, 200);
+  const batchId = ok.body.batches[0].id;
+  assert.equal((await handle({ path: "/items/1", headers: annex })).body.onHand, 3);
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 10);
+  // cooking at annex cannot use main's stock
+  const cook = await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 4 } });
+  assert.equal(cook.status, 409);
+  // stock-takes
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "dry" } })).body.error.code, "unknown_location");
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId, counted: 1 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: annex, body: { batchId: 1, counted: 1 } })).body.error.code, "unknown_batch");
+  await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: annex, body: { batchId, counted: 2 } });
+  const fin = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: annex });
+  assert.deepEqual(fin.body.lines, [{ batchId, expected: 3, counted: 2, diff: -1 }]);
+  assert.equal(store.data.batches.find((b) => b.id === 1).qty, 4);
+});
+
+test("cooking at annex uses annex stock", async () => {
+  const { handle } = app();
+  for (const itemId of [1, 3, 5, 6]) {
+    const o = await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId, qty: 10 }] } });
+    await handle({ method: "POST", path: `/orders/${o.body.id}/send` });
+    await handle({ method: "POST", path: `/orders/${o.body.id}/receive`, headers: annex, body: { lots: [{ lot: "z", expires: null, location: "annex-fridge" }] } });
+  }
+  const cook = await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 4 } });
+  assert.equal(cook.status, 200);
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 10);
+});
